import{_ as n,C as s,o as e,c as m,a2 as r,j as i,E as o,a as t}from"./chunks/framework.Dsdg6H41.js";const D=JSON.parse(`{"title":"20-dars (Mentor). Algoritm tushunchasi va algoritmik fikrlash","description":"","frontmatter":{"title":"20-dars (Mentor). Algoritm tushunchasi va algoritmik fikrlash","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"week":{"n":7,"link":"/mentor/8-sinf-cs/hafta-07/"},"g":20,"title":"Algoritm tushunchasi va algoritmik fikrlash","lead":"Dasturlash — bu kompyuterga nima qilish kerakligini tushuntirishdir. Kompyuter buyruqlaringizni to'g'ri bajarishi uchun esa algoritmik fikrlashni bilishingiz shart. Bugun buyuk bobomiz Al-Xorazmiy asos solgan tushuncha bilan tanishamiz!","slide":"/slaydlar/8-sinf-cs/hafta-07/dars-2.html","test":"/slaydlar/8-sinf-cs/hafta-07/dars-2-test.html","student_link":"/8-sinf-cs/hafta-07/dars-2","tabs":[{"g":19,"link":"/mentor/8-sinf-cs/hafta-07/dars-1","current":false},{"g":20,"link":"/mentor/8-sinf-cs/hafta-07/dars-2","current":true},{"g":21,"link":"/mentor/8-sinf-cs/hafta-07/dars-3","current":false}],"prev":{"g":19,"title":"Kiberxavfsizlik va shaxsiy ma’lumotlarni himoya qilish asoslari","link":"/mentor/8-sinf-cs/hafta-07/dars-1"},"next":{"g":21,"title":"Flowalgorithm interfeysi va blok-sxema elementlari bilan ishlash","link":"/mentor/8-sinf-cs/hafta-07/dars-3"}}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-07/dars-2.md","filePath":"mentor/8-sinf-cs/hafta-07/dars-2.md"}`),h={name:"mentor/8-sinf-cs/hafta-07/dars-2.md"},d={class:"blk"},g={id:"darsning-maqsadi",tabindex:"-1"},u={class:"blk"},k={id:"kutiladigan-natija",tabindex:"-1"},b={class:"blk"},y={id:"kerakli-jihozlar",tabindex:"-1"},q={class:"blk"},v={id:"dars-rejasi-80-daqiqa",tabindex:"-1"},f={class:"blk"},p={id:"konspekt-mentor-aytadigan-matn",tabindex:"-1"},c={class:"blk"},z={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},x={class:"blk"},_={id:"tezkor-nazorat-savollari",tabindex:"-1"},A={class:"blk"},j={id:"uyga-vazifa",tabindex:"-1"};function T(P,a,I,$,S,C){const l=s("Icon");return e(),m("div",null,[a[25]||(a[25]=r("<p><strong>Fan:</strong> Computer Science Foundation<br><strong>Sinf:</strong> 8-sinf<br><strong>Hafta:</strong> 7-hafta, 2-dars (umumiy 20-dars)<br><strong>Davomiyligi:</strong> 80 daqiqa<br><strong>Bob:</strong> III-bob. Algoritmlash, Flowalgorithm va dasturlash asoslari (1-dars)<br><strong>Manba:</strong> O&#39;quv dasturi, III-bob: «Algoritm tushunchasi va algoritmik fikrlash. Algoritm tushunchasi, vazifasi va kundalik hayotdagi misollar. Algoritmning asosiy xossalari: aniqlik, ketma-ketlik, natijaviylik. Algoritmik fikrlash va masalani bosqichlarga ajratish.»</p><hr>",2)),i("div",d,[i("h2",g,[o(l,{name:"file-text"}),a[0]||(a[0]=t(" Darsning maqsadi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#darsning-maqsadi","aria-label":'Permalink to "<Icon name="file-text" /> Darsning maqsadi"'},"​",-1))]),a[2]||(a[2]=i("p",null,"O'quvchilarga algoritm tushunchasi, uning kelib chiqish tarixi (Muhammad al-Xorazmiy merosi), kundalik hayotdagi va dasturlashdagi o'rni hamda algoritmning asosiy xossalarini tushuntirish; algoritmik fikrlash ko'nikmalarini (dekompozitsiya, namunalarni topish, abstraktsiya) rivojlantirish.",-1))]),i("div",u,[i("h2",k,[o(l,{name:"file-text"}),a[3]||(a[3]=t(" Kutiladigan natija ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#kutiladigan-natija","aria-label":'Permalink to "<Icon name="file-text" /> Kutiladigan natija"'},"​",-1))]),a[5]||(a[5]=i("ul",null,[i("li",null,"Algoritm atamasi nima ekanini va uning Muhammad al-Xorazmiy nomi bilan bog'liqligini biladi;"),i("li",null,"Kundalik hayotdan va matematikadan algoritmlarga aniq misollar keltira oladi;"),i("li",null,"Algoritmning 5 ta asosiy xossasini (diskretlik, aniqlik, tushunarlilik, natijaviylik, ommaviylik) farqlaydi va amalda tekshira oladi;"),i("li",null,"Algoritmik fikrlashning 4 ta ustunini (dekompozitsiya, namuna, abstraksiya, algoritm) tushunadi;"),i("li",null,"Masalani mayda qadamlarga ajratib, to'g'ri ketma-ketlikda yo'riqnoma tuza oladi.")],-1))]),i("div",b,[i("h2",y,[o(l,{name:"file-text"}),a[6]||(a[6]=t(" Kerakli jihozlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#kerakli-jihozlar","aria-label":'Permalink to "<Icon name="file-text" /> Kerakli jihozlar"'},"​",-1))]),a[8]||(a[8]=i("ul",null,[i("li",null,"Kompyuter va proyektor (slaydlar namoyishi uchun)"),i("li",null,"Doska va bo'r/marker (algoritmlarni chizish va tahlil qilish uchun)"),i("li",null,"O'quvchi daftari va qalam")],-1)),a[9]||(a[9]=i("hr",null,null,-1))]),i("div",q,[i("h2",v,[o(l,{name:"file-text"}),a[10]||(a[10]=t(" Dars rejasi (80 daqiqa) ",-1)),a[11]||(a[11]=i("a",{class:"header-anchor",href:"#dars-rejasi-80-daqiqa","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi (80 daqiqa)"'},"​",-1))]),a[12]||(a[12]=r('<table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>00–08</td><td>Takrorlash</td><td>19-dars (Kiberxavfsizlik va akkaunt himoyasi xulosasi)</td></tr><tr><td>08–25</td><td>Yangi mavzu 1</td><td>Algoritm tushunchasi, al-Xorazmiy merosi va kundalik misollar</td></tr><tr><td>25–40</td><td>Yangi mavzu 2</td><td>Algoritmning 5 ta oltin xossasi (aniqlik, diskretlik, natijaviylik...)</td></tr><tr><td>40–45</td><td>Tanaffus</td><td>Qisqa dam olish va mantiqiy jumboq</td></tr><tr><td>45–60</td><td>Yangi mavzu 3</td><td>Algoritmik fikrlash (Computational Thinking): dekompozitsiya va abstraksiya</td></tr><tr><td>60–75</td><td>Amaliyot</td><td>3 ta amaliy topshiriq: robot yo&#39;li, choy damlash, matematika algoritmi</td></tr><tr><td>75–80</td><td>Xulosa</td><td>Tezkor nazorat savollari, dars yakuni, uyga vazifa</td></tr></tbody></table><hr>',2))]),i("div",f,[i("h2",p,[o(l,{name:"file-text"}),a[13]||(a[13]=t(" Konspekt (mentor aytadigan matn) ",-1)),a[14]||(a[14]=i("a",{class:"header-anchor",href:"#konspekt-mentor-aytadigan-matn","aria-label":'Permalink to "<Icon name="file-text" /> Konspekt (mentor aytadigan matn)"'},"​",-1))]),a[15]||(a[15]=r('<h3 id="_1-algoritm-nima-va-u-qayerdan-kelgan" tabindex="-1">1. Algoritm nima va u qayerdan kelgan? <a class="header-anchor" href="#_1-algoritm-nima-va-u-qayerdan-kelgan" aria-label="Permalink to &quot;1. Algoritm nima va u qayerdan kelgan?&quot;">​</a></h3><p>Bugun biz butun dasturlash va axborot texnologiyalarining yuragi bo&#39;lgan yangi katta bobni — <strong>Algoritmlash va dasturlash asoslari</strong>ni boshlaymiz!</p><p><strong>«Algoritm»</strong> so&#39;zi bizning buyuk vatandoshimiz, buyuk qomusiy olim <strong>Muhammad ibn Muso al-Xorazmiy</strong> (783–850) nomining lotinchalashtirilgan shakli — <em>«Algoritmi»</em> dan kelib chiqqan. Al-Xorazmiy o&#39;nlik sanoq tizimida arifmetik amallarni qadamma-qadam bajarish qoidalarini fanga kiritgan olimdir.</p><blockquote><p><strong>Algoritm</strong> — bu qo&#39;yilgan maqsadga erishish yoki masalani yechish uchun ijrochi bajarishi shart bo&#39;lgan buyruqlarning aniq, tushunarli va tartibli ketma-ketligidir.</p></blockquote><p>Algoritmni bajaruvchi shaxs yoki qurilma <strong>Ijrochi (Executor)</strong> deyiladi. Ijrochi inson, robot, kompyuter dasturi yoki hatto kir yuvish mashinasi bo&#39;lishi mumkin.</p><p><strong>Hayotiy misollar:</strong></p><ol><li><em>Choy damlash algoritmi:</em> Choynakni yuvish → suv qaynatish → quruq choy solish → qaynoq suv quyish → 3–5 daqiqa damlash.</li><li><em>Maktabga borish algoritmi:</em> Uyg&#39;onish → yuvinish → kiyinish → nonushta qilish → sumkani tekshirish → maktabga yo&#39;l olish.</li><li><em>Bankomatdan pul yechish:</em> Kartani kiritish → PIN-kodni terish → summani tanlash → pulni olish → kartani qaytarib olish.</li></ol><p>Agar birorta qadamning o&#39;rni almashsa yoki tushib qolsa, kutilgan natijaga erishib bo&#39;lmaydi!</p><h3 id="_2-algoritmning-5-ta-asosiy-xossasi" tabindex="-1">2. Algoritmning 5 ta asosiy xossasi <a class="header-anchor" href="#_2-algoritmning-5-ta-asosiy-xossasi" aria-label="Permalink to &quot;2. Algoritmning 5 ta asosiy xossasi&quot;">​</a></h3><p>Har qanday ketma-ketlikni ham algoritm deb bo&#39;lmaydi. Algoritm quyidagi 5 ta xossaga javob berishi shart:</p><ol><li><strong>Diskretlik (bo&#39;laklilik):</strong> Algoritm alohida, tugallangan qadamlardan iborat bo&#39;lishi kerak. Har bir qadam oldingisi tugagandan so&#39;ng boshlanadi.</li><li><strong>Aniqlik (determinallik):</strong> Har bir buyruq barcha uchun bir xil tushunilishi, noaniqlik va ikkilanish bo&#39;lmasligi kerak. «Biroz tuz soling» buyrug&#39;i noaniq, lekin «1 choy qoshiq tuz soling» buyrug&#39;i aniqdir.</li><li><strong>Tushunarlilik:</strong> Buyruqlar ijrochining buyruqlar tizimiga (tushunish doirasiga) mos bo&#39;lishi shart. Kompyuter faqat o&#39;zi biladigan buyruqlarni (kodni) tushunadi.</li><li><strong>Natijaviylik (cheklilik):</strong> Algoritm chekli sondagi qadamlardan so&#39;ng albatta tugashi va kutilgan natijani berishi kerak. Agar algoritm abadiy aylanib qolsa (cheksiz sikl), u noto&#39;g&#39;ri tuzilgan hisoblanadi.</li><li><strong>Ommaviylik:</strong> Algoritm faqat bitta xususiy holat uchun emas, balki bir turdagi barcha masalalar uchun ishlashi kerak. Masalan: «2 va 3 sonlarini qo&#39;shish» emas, «Ixtiyoriy A va B sonlarini qo&#39;shish» algoritmi ommaviydir.</li></ol><h3 id="_3-algoritmik-fikrlash-computational-thinking" tabindex="-1">3. Algoritmik fikrlash (Computational Thinking) <a class="header-anchor" href="#_3-algoritmik-fikrlash-computational-thinking" aria-label="Permalink to &quot;3. Algoritmik fikrlash (Computational Thinking)&quot;">​</a></h3><p>Dasturchilar muammoni qanday yechadilar? Ular <strong>algoritmik fikrlash</strong> usulidan foydalanadilar. U 4 ta bosqichdan iborat:</p><ol><li><strong>Dekompozitsiya (Decomposition):</strong> Katta va murakkab masalani bir nechta mayda, oson qismlarga bo&#39;lish. Masalan: butun o&#39;yinni bir vaqtda yaratish emas, avval qahramon harakati, keyin to&#39;siqlar, keyin ochkolar hisobini yaratish.</li><li><strong>Namunalarni aniqlash (Pattern Recognition):</strong> Masaladagi o&#39;xshashliklar va takrorlanishlarni topish. Masalan: har bir darsda mavzu o&#39;rganilib, keyin amaliyot qilinishi.</li><li><strong>Abstraksiya (Abstraction):</strong> Masalaga bevosita aloqasi bo&#39;lmagan mayda ikkinchi darajali detallarni chetga surib, faqat eng muhim nuqtalarga e&#39;tibor qaratish.</li><li><strong>Algoritm loyihalash (Algorithm Design):</strong> Qadamma-qadam aniq yo&#39;riqnoma va sxema tuzish.</li></ol><p><strong>Algoritmni ifodalash usullari:</strong></p><ul><li><em>So&#39;zlar orqali (matnli):</em> O&#39;zbek yoki ingliz tilidagi og&#39;zaki/yozma qadamlar.</li><li><em>Blok-sxema orqali (grafik):</em> Maxsus geometrik shakllar yordamida (keyingi 21-darsda Flowgorithm bilan batafsil o&#39;rganamiz).</li><li><em>Dastur kodi orqali:</em> Python, C++, JavaScript kabi dasturlash tillarida.</li></ul><hr>',17))]),i("div",c,[i("h2",z,[o(l,{name:"file-text"}),a[16]||(a[16]=t(" Amaliy topshiriqlar va yechimlar ",-1)),a[17]||(a[17]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[18]||(a[18]=r('<h3 id="_1-topshiriq-kundalik-jarayon-algoritmini-tuzish-oson" tabindex="-1">1-topshiriq: Kundalik jarayon algoritmini tuzish (Oson) <a class="header-anchor" href="#_1-topshiriq-kundalik-jarayon-algoritmini-tuzish-oson" aria-label="Permalink to &quot;1-topshiriq: Kundalik jarayon algoritmini tuzish (Oson)&quot;">​</a></h3><p>«Telefon quvvatlagichini ulash va telefonni 100% quvvatlash» jarayoni uchun 5–6 qadamdan iborat matnli algoritm yozing va unda diskretlik hamda natijaviylik xossalarini ko&#39;rsating.</p><p><strong>Kutiladigan natija:</strong> Aniq ketma-ketlikdagi qadamlar va algoritmning yakunlanish sharti.</p><p><strong>Yechim:</strong></p><ol><li>1-qadam: Quvvatlagich blokini elektr rozetkasiga ulash.</li><li>2-qadam: Kabelning ikkinchi uchini smartfon portiga ulash.</li><li>3-qadam: Ekranda quvvatlash belgisi paydo bo&#39;lganini tekshirish.</li><li>4-qadam: Quvvat darajasi 100% ga yetguncha kutish.</li><li>5-qadam: Quvvatlagich kabelini telefondan ajratish.</li><li>6-qadam: Blokni rozetkadan sug&#39;urish (Tugash). <em>Xossalar:</em> Har bir qadam alohida raqamlangan (diskretlik) va telefon 100% bo&#39;lgach jarayon tugaydi (natijaviylik).</li></ol><hr><h3 id="_2-topshiriq-to-g-ri-to-rtburchak-yuzi-va-perimetrini-hisoblash-algoritmi-o-rta" tabindex="-1">2-topshiriq: To&#39;g&#39;ri to&#39;rtburchak yuzi va perimetrini hisoblash algoritmi (O&#39;rta) <a class="header-anchor" href="#_2-topshiriq-to-g-ri-to-rtburchak-yuzi-va-perimetrini-hisoblash-algoritmi-o-rta" aria-label="Permalink to &quot;2-topshiriq: To&#39;g&#39;ri to&#39;rtburchak yuzi va perimetrini hisoblash algoritmi (O&#39;rta)&quot;">​</a></h3><p>To&#39;g&#39;ri to&#39;rtburchakning eni ($a$) va bo&#39;yi ($b$) berilgan. Uning yuzi ($S = a \\times b$) va perimetrini ($P = 2 \\times (a + b)$) hisoblash uchun universal (ommaviy) algoritm tuzing.</p><p><strong>Kutiladigan natija:</strong> Kiritish, hisoblash va natijani chiqarish bosqichlaridan iborat aniq algoritm.</p><p><strong>Yechim:</strong></p><ol><li>Boshlanish.</li><li>$a$ sonini kiritish (eni).</li><li>$b$ sonini kiritish (bo&#39;yi).</li><li>$S = a \\times b$ formulasiga ko&#39;ra yuzani hisoblash.</li><li>$P = 2 \\times (a + b)$ formulasiga ko&#39;ra perimetrni hisoblash.</li><li>Natijalar: $S$ va $P$ qiymatlarini ekranga chiqarish.</li><li>Tugash. <em>Xossasi:</em> Ommaviylik — $a$ va $b$ o&#39;rniga ixtiyoriy musbat sonlar berilsa ham algoritm to&#39;g&#39;ri ishlaydi.</li></ol><hr><h3 id="_3-topshiriq-robot-harakati-va-dekompozitsiya-qiyin" tabindex="-1">3-topshiriq: Robot harakati va dekompozitsiya (Qiyin) <a class="header-anchor" href="#_3-topshiriq-robot-harakati-va-dekompozitsiya-qiyin" aria-label="Permalink to &quot;3-topshiriq: Robot harakati va dekompozitsiya (Qiyin)&quot;">​</a></h3><p>Tasavvur qiling, doskada to&#39;siqlar bor. Robot boshlang&#39;ich nuqtadan marraga borishi kerak. Robot faqat 3 ta buyruqni tushunadi: <code>Oldinga 1 qadam</code>, <code>O&#39;ngga buril 90°</code>, <code>Chapga buril 90°</code>. Vazifa: Robotni to&#39;siqlarni aylanib o&#39;tib marraga eltuvchi algoritm tuzing va xato buyruq kiritilganda ijrochi nega to&#39;xtab qolishini (tushunarlilik xossasi) izohlang.</p><p><strong>Kutiladigan natija:</strong> Cheklangan buyruqlar tizimi asosida tuzilgan algoritm va ijrochi doirasi tushunchasi.</p><p><strong>Yechim:</strong></p><ol><li>Boshlanish.</li><li><code>Oldinga 1 qadam</code></li><li><code>Oldinga 1 qadam</code> (to&#39;siq oldiga yetib keldi)</li><li><code>O&#39;ngga buril 90°</code></li><li><code>Oldinga 1 qadam</code></li><li><code>Chapga buril 90°</code></li><li><code>Oldinga 1 qadam</code></li><li><code>Oldinga 1 qadam</code> (marraga yetdi)</li><li>Tugash. <em>Izoh:</em> Agar robotga «Sakrab o&#39;t» yoki «Tezroq yugur» deb buyruq berilsa, robot uni tushunmaydi va to&#39;xtab qoladi. Chunki bu buyruq robotning ruxsat etilgan buyruqlar tizimida (tushunarlilik xossasi) mavjud emas!</li></ol><hr>',18))]),i("div",x,[i("h2",_,[o(l,{name:"file-text"}),a[19]||(a[19]=t(" Tezkor nazorat savollari ",-1)),a[20]||(a[20]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[21]||(a[21]=r("<ol><li><strong>«Algoritm» so&#39;zi kimning nomidan kelib chiqqan?</strong><br><em>Javob:</em> Buyuk o&#39;zbek allomasi Muhammad ibn Muso al-Xorazmiy nomidan.</li><li><strong>Algoritmning diskretlik xossasi nimani anglatadi?</strong><br><em>Javob:</em> Algoritm alohida, tugallangan qadamlardan iborat bo&#39;lishini.</li><li><strong>Natijaviylik xossasi buzilsa nima yuz beradi?</strong><br><em>Javob:</em> Dastur cheksiz siklga tushib qoladi, hech qachon to&#39;xtamaydi va natija bermaydi.</li><li><strong>Dekompozitsiya nima?</strong><br><em>Javob:</em> Katta va murakkab masalani kichik, oson hal qilinadigan bo&#39;laklarga ajratish.</li></ol><hr>",2))]),i("div",A,[i("h2",j,[o(l,{name:"house"}),a[22]||(a[22]=t(" Uyga vazifa ",-1)),a[23]||(a[23]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[24]||(a[24]=i("ol",null,[i("li",null,"O'zingiz yoqtirgan taomni tayyorlash yoki sevimli o'yiningizdagi bir bosqichni o'tish algoritmini 6–8 qadamda daftarga yozing."),i("li",null,[t("Yozgan algoritmingizda 5 ta xossa (diskretlik, aniqlik, tushunarlilik, natijaviylik, ommaviylik) bajarilganligini tekshiring (batafsil: "),i("code",null,"uyga-vazifa.md"),t(").")])],-1))])])}const O=n(h,[["render",T]]);export{D as __pageData,O as default};
